#nullable enable // autogenerated

using MVZ2.GameContent.Seeds;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.nestingTNT_Evoke)]
    public class NestingTNT_Evoke : ContraptionEvokeBehaviour
    {
        public NestingTNT_Evoke(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Evoke(Entity entity)
        {
            base.Evoke(entity);
            for (int i = 0; i < BLUEPRINT_PRODUCE_COUNT; i++)
            {
                NestingTNT.SpawnBlueprintPickup(entity, entity.GetCenter(), VanillaBlueprintID.nestingTNT);
            }
            entity.PlaySound(VanillaSoundID.potion);
        }
        public const int BLUEPRINT_PRODUCE_COUNT = 2;
    }
}
